input.command:
python3 -c "
import json
with open('DATA/products/CoachForce.json') as f:
    data = json.load(f)
# look at feedback structure in full detail
for i, doc in enumerate(data['documents']):
    if doc.get('feedback'):
        print(i, 'feedback type:', type(doc['feedback']).__name__)
        fb = doc['feedback']
        if isinstance(fb, list):
            for item in fb:
                print('  fb item:', item)
        elif isinstance(fb, dict):
            print('  fb:', fb)
        print()
"

